(function () {
      var baseTitle = 'AdiNika Creations.com — Handmade Pipe-Cleaner Crafts';
      var today = new Date();
      document.getElementById('year').textContent = today.getFullYear();
      document.body.classList.add('motion-ready');

      function setSeasonalWeather(date) {
        var month = date.getMonth() + 1;
        var day = date.getDate();
        var season = 'winter';
        var icons = ['snowball','snowflake','snow-crystal'];
        if (month >= 5 && month <= 6) {
          season = 'sunshine'; icons = ['sun-ray'];
        } else if (month >= 7 && month <= 8) {
          season = 'rain'; icons = ['raindrop'];
        } else if (month === 9 || (month === 10 && day < 15)) {
          season = 'autumn'; icons = ['autumn-leaf'];
        } else if ((month === 10 && day >= 15) || month === 11) {
          season = 'halloween'; icons = ['pumpkin','ghost','boo'];
        } else if (month === 12) {
          season = 'christmas'; icons = ['tree','candy','toy'];
        }
        var weather = document.querySelector('.fall-leaves');
        if (!weather) return;
        weather.setAttribute('data-season', season);
        weather.querySelectorAll('.fall-leaf').forEach(function (item, index) {
          var icon = icons[index % icons.length];
          var use = item.querySelector('use');
          item.setAttribute('data-icon', icon);
          use.setAttribute('href', icon === 'autumn-leaf' ? '#autumn-leaf' : '#seasonal-' + icon);
        });
      }
      setSeasonalWeather(today);

      var themeData = {
        birthdays: {
          title: 'Birthday magic, made by hand.',
          quote: 'A birthday is one bright day in a beautiful story. We twist color, joy and a little wonder into keepsakes made to celebrate the person at its heart.',
          prefix: 'birthday',
          names: ['Tiny Birthday Panda','Whimsy Cake Topper','A Bouquet of Wishes','Party Crown','Balloon Cheer','Joyful Swirls','Cupcake Keepsake','Little Gift Box','Milestone Number','Flower Garland','Birthday Bear','Celebration Basket']
        },
        festivals: {
          title: 'Color for every celebration.',
          quote: 'Festivals bring homes and hearts together. Each handmade detail carries color, warmth and the happiness of gathering with the people we love.',
          prefix: 'festivals',
          names: ['Glowing Diya','Marigold Circle','Celebration Medallion','Festive Toran','Little Lantern','Twinkling Star','Flower Basket','Joyful Peacock','Welcome Wreath','Festive Gift','Hanging Bells','Celebration Blooms']
        },
        'home-decor': {
          title: 'Small wonders for happy corners.',
          quote: 'A home becomes yours through the little things. Let soft color, playful shapes and handmade warmth turn an everyday corner into a place that smiles back.',
          prefix: 'home-decor',
          names: ['Forever Vase','Garden Wreath','Curtain Tassel','Shelf Panda','Tiny Plant','Color Circle','Hanging Star','Soft Rainbow','Mini Bonsai','Mirror Garland','Shelf Sculpture','Floral Hoop']
        },
        personalized: {
          title: 'Your idea, given a little life.',
          quote: 'Made for your occasion, shaped around your wishes and crafted by loving hands. We respect your idea, bring beauty to every detail and give your love a form you can hold.',
          prefix: 'personalized',
          names: ['Together Always','Favorite Blooms','Pet Keepsake','Memory Frame','Friendship Knot','Little Family','Your Panda','Heart in Hand','Creative Spark','Special Crown','Gift of You','One-of-a-Kind Twist']
        }
      };

      var homeView = document.getElementById('homeView');
      var themePage = document.getElementById('themePage');
      var sampleGrid = document.getElementById('sampleGrid');
      var themeTitle = document.getElementById('themeTitle');
      var themeQuote = document.getElementById('themeQuote');
      var dialog = document.querySelector('.lightbox');
      var dialogImage = dialog.querySelector('img');
      var dialogTitle = dialog.querySelector('p');
      var closeButton = dialog.querySelector('.close');
      var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      function openLightbox(src, alt, title) {
        dialogImage.src = src; dialogImage.alt = alt; dialogTitle.textContent = title; dialog.showModal();
      }

      function openTheme(key, updateHistory) {
        var data = themeData[key]; if (!data) return;
        sampleGrid.innerHTML = '';
        themeTitle.textContent = data.title; themeQuote.textContent = data.quote;
        data.names.forEach(function (name, index) {
          var number = String(index).padStart(2, '0');
          var src = 'assets/gallery/' + data.prefix + '-' + number + '.jpg';
          var card = document.createElement('button');
          card.type = 'button'; card.className = 'sample-card';
          card.setAttribute('aria-label', 'View ' + name);
          card.innerHTML = '<figure><div class="sample-image"><img src="' + src + '" alt="Handmade pipe-cleaner ' + name.toLowerCase() + ' sample" /></div><figcaption class="magic-text">' + name + '</figcaption></figure>';
          card.addEventListener('click', function () { openLightbox(src, 'Handmade pipe-cleaner ' + name.toLowerCase() + ' sample', name); });
          sampleGrid.appendChild(card);
        });
        homeView.hidden = true; themePage.classList.add('active');
        document.title = data.title + ' — AdiNika Creations.com';
        if (updateHistory) history.pushState({ theme:key }, '', '#theme=' + key);
        window.scrollTo(0, 0); themeTitle.focus && themeTitle.focus();
      }

      function showHome(updateHistory) {
        themePage.classList.remove('active'); homeView.hidden = false; document.title = baseTitle;
        if (updateHistory) history.pushState({}, '', location.pathname + location.search);
        window.scrollTo(0, 0);
      }

      document.querySelectorAll('[data-theme]').forEach(function (button) {
        button.addEventListener('click', function () { openTheme(button.getAttribute('data-theme'), true); });
      });
      document.getElementById('backHome').addEventListener('click', function () { showHome(true); });
      document.querySelector('[data-back-home]').addEventListener('click', function () { showHome(true); });
      window.addEventListener('popstate', function () {
        var match = location.hash.match(/^#theme=(.+)$/); if (match && themeData[match[1]]) openTheme(match[1], false); else showHome(false);
      });

      var pieces = document.querySelectorAll('.piece');
      function playPanda(piece) {
        var video = piece.querySelector('.panda-motion'); if (!video || reduceMotion) return;
        video.currentTime = 0; var playPromise = video.play(); if (playPromise) playPromise.catch(function () { piece.classList.remove('is-video-playing'); });
      }
      function resetPanda(piece) {
        var video = piece.querySelector('.panda-motion'); if (!video || piece.classList.contains('is-playing')) return;
        video.pause(); video.currentTime = 0; piece.classList.remove('is-video-playing');
      }
      var pandaPiece = document.querySelector('.panda'); var pandaVideo = pandaPiece.querySelector('.panda-motion');
      pandaVideo.addEventListener('playing', function () { pandaPiece.classList.add('is-video-playing'); });
      ['ended','pause','error'].forEach(function (eventName) { pandaVideo.addEventListener(eventName, function () { pandaPiece.classList.remove('is-video-playing'); }); });

      function activatePiece(piece) {
        if (!piece.classList.contains('is-playing') && !reduceMotion) {
          pieces.forEach(function (item) { item.classList.remove('is-playing'); }); piece.classList.add('is-playing'); if (piece.classList.contains('panda')) playPanda(piece); return;
        }
        var image = piece.querySelector('img'); var src = piece.classList.contains('flowers') ? 'data:image/jpeg;base64,' : image.src;
        openLightbox(src, image.alt, piece.querySelector('h3').textContent);
      }
      pieces.forEach(function (piece) {
        piece.addEventListener('pointerenter', function (event) { if (event.pointerType !== 'touch' && piece.classList.contains('panda')) playPanda(piece); });
        piece.addEventListener('click', function () { activatePiece(piece); });
        piece.addEventListener('keydown', function (event) { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); activatePiece(piece); } });
        piece.addEventListener('pointermove', function (event) {
          if (event.pointerType === 'touch' || reduceMotion) return; var box = piece.getBoundingClientRect(); var x = (event.clientX-box.left)/box.width-.5; var y = (event.clientY-box.top)/box.height-.5;
          piece.style.transform = 'rotateY(' + (x*2.6) + 'deg) rotateX(' + (y*-2.2) + 'deg)';
        });
        piece.addEventListener('pointerleave', function () { piece.style.transform=''; if (piece.classList.contains('panda')) resetPanda(piece); });
      });

      var reveals = document.querySelectorAll('.reveal');
      if ('IntersectionObserver' in window && !reduceMotion) {
        var observer = new IntersectionObserver(function (entries) { entries.forEach(function (entry) { if (entry.isIntersecting) { entry.target.classList.add('is-visible'); observer.unobserve(entry.target); } }); }, {threshold:.12});
        reveals.forEach(function (element,index) { element.style.animationDelay = Math.min(index%3,2)*90 + 'ms'; observer.observe(element); });
      } else { reveals.forEach(function (element) { element.classList.add('is-visible'); }); }

      closeButton.addEventListener('click', function () { dialog.close(); });
      dialog.addEventListener('click', function (event) { if (event.target === dialog) dialog.close(); });
      var initialTheme = location.hash.match(/^#theme=(.+)$/); if (initialTheme && themeData[initialTheme[1]]) openTheme(initialTheme[1], false);
    })();
